def _pravit(p: Path, pravki: list, dopisat: str = "") -> int:
    if not p.exists():
        print(f"  {p.name}: файла нет")
        return 0
    txt = p.read_text(encoding="utf-8")
    if MARKER in txt:
        print(f"  {p.name}: уже стоит")
        return 0

    novy, sdelano = txt, []
    for imya, staroe, novoe in pravki:
        n = novy.count(staroe)
        if n != 1:
            print(f"    ! {imya}: якорь встречается {n} раз(а) — пропускаю")
            continue
        novy = novy.replace(staroe, novoe, 1)
        sdelano.append(imya)

    if dopisat and dopisat not in novy:
        # строка дня должна встать В ТАБЛИЦУ, а не в конец файла:
        # после таблицы идут маркеры прошлых патчей, и markdown
        # отрисовал бы строку отдельным текстом, а не рядом с днями
        stroki = novy.splitlines()
        posledniy = max((i for i, s in enumerate(stroki)
                         if s.startswith("| ")), default=-1)
        if posledniy >= 0:
            stroki.insert(posledniy + 1, dopisat.rstrip("\n"))
            novy = "\n".join(stroki) + "\n"
            sdelano.append("день вписан в таблицу")
        else:
            novy = novy.rstrip("\n") + "\n" + dopisat
            sdelano.append("дописано в конец (таблицы не нашёл)")

    if not sdelano:
        print(f"  {p.name}: менять нечего")
        return 0
    if MARKER not in novy:
        novy = novy.rstrip("\n") + f"\n\n<!-- {MARKER} -->\n"

    if not SUHO:
        shutil.copy2(p, p.with_suffix(p.suffix + ".bak_doki"))
        p.write_text(novy, encoding="utf-8")
    print(f"  {p.name}: {'готов' if SUHO else 'поправлен'} — "
          + ", ".join(sdelano))
    return 1


def main():
    print()
    print("ДОКУМЕНТЫ ДОГОНЯЮТ ДЕЛО" + ("  · СУХОЙ ПРОГОН" if SUHO else ""))
    print("корень:", _REPO)
    print()

    vsego = 0

    print("1. ЧЕРТЁЖ — глава «Ключ и клетка»:")
    vsego += _pravit(_REPO / "ЧЕРТЁЖ_ЕДИНИЦЫ.md", [], GLAVA)

    print()
    print("2. ЗАМЫСЛЫ — помечены историей:")
    for imya in ("ZAMYSEL_09_09.md", "ZAMYSEL_09_09_chast2.md"):
        p = _REPO / imya
        if not p.exists():
            print(f"  {imya}: файла нет")
            continue
        txt = p.read_text(encoding="utf-8")
        if MARKER in txt:
            print(f"  {imya}: уже стоит")
            continue
        novy = SHAPKA_ZAMYSLA + txt.rstrip("\n") + f"\n\n<!-- {MARKER} -->\n"
        if not SUHO:
            shutil.copy2(p, p.with_suffix(".md.bak_doki"))
            p.write_text(novy, encoding="utf-8")
        print(f"  {imya}: {'готов' if SUHO else 'помечен'}")
        vsego += 1

    print()
    print("3. БИРЖА — день дописан, устаревшее поправлено:")
    vsego += _pravit(_REPO / "БИРЖА.md", PRAVKI_BIRZHA, DEN)

    print()
    if SUHO:
        print("Сухой прогон: на диске ничего не изменилось.")
    else:
        print(f"Тронуто документов: {vsego}. Бэкапы — .bak_doki")
    print()


if __name__ == "__main__":
    main()
